import{z as o,x as B,o as l,c as d,q as A,j as i,D as e,d as t,s,S as n,b as E}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"视图与物化","description":"","frontmatter":{"title":"视图与物化","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/views-materialize.md","filePath":"cs/views-materialize.md","lastUpdated":1791063341000}'),p={name:"cs/views-materialize.md"};function m(D,a,u,f,F,T){const r=B("Mermaid");return l(),d("div",null,[a[2]||(a[2]=A('<h1 id="视图与物化" tabindex="-1">视图与物化 <a class="header-anchor" href="#视图与物化" aria-label="Permalink to &quot;视图与物化&quot;">​</a></h1><div class="epigraph"><p>视图是命名的查询；虚的每次重算，实的把结果存住，更新则变成维护问题。</p><footer>—— 据 Date 对视图；Gupta and Mumick 对物化视图维护的整理</footer></div><p><a href="/cs/bcnf-3nf">上一课</a>把宽表按依赖切开。本课不重做 3NF 合成。缺口是：用户仍想看见「一张订单宽表」，而基表已经分解。视图把一条声明查询命名成虚拟关系；物化则把结果写成真实存储，用空间换重复求值。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>分解之后，每次查询都要连接。若把连接写成应用里的字符串，模式一变，字符串全碎。缺口不是新代数，而是<strong>外模式</strong>：视图的指称是某棵查询树，对用户仍是关系。虚视图不占堆文件；物化视图占存储，基表一改就要维护，否则读到的是过期快照。</p><p>本课不把「可更新视图」的全部定理写完，只钉：读视图 = 求值或读副本；写视图往往没有唯一的基表翻译。</p><p><span class="marginnote">Codd 的三层模式：内模式存储、概念模式基表、外模式视图。数据独立性的用户侧就是这一层，与<a href="/cs/relational-model">关系模型</a>第一课的独立性相接。</span></p><p><span class="marginnote">术语翻译：视图就是用「给一条查询起个名字」的手段来做「让用户看见一张其实不存在的表」的事——虚视图每次打开都现场重算，物化视图则把这次重算的结果真的存下来，从此多了一件事：基表一变它就过期，得有人去维护。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>虚视图：打开查询时把视图名换成定义树，再走<a href="/cs/query-rewrite">改写</a>与计划。物化：把结果存成表，选立即维护或延迟刷新。增量维护：基表 delta 推出视图 delta，避免全量重算。本课不展开维护规则的代数，只要求维护保持与定义树一致。</p>',10)),(l(),i(n,null,{default:e(()=>[s(r,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20BASE%5B%22%E5%9F%BA%E8%A1%A8%22%5D%20--%3E%20VV%5B%22%E8%99%9A%E8%A7%86%E5%9B%BE%3A%20%E5%B1%95%E5%BC%80%E6%A0%91%22%5D%0A%20%20BASE%20--%3E%20MV%5B%22%E7%89%A9%E5%8C%96%3A%20%E5%AD%98%E7%BB%93%E6%9E%9C%22%5D%0A%20%20MV%20--%3E%20MAINT%5B%22%E5%A2%9E%E9%87%8F%20%2F%20%E5%88%B7%E6%96%B0%22%5D%0A%20%20VV%20--%3E%20PAGE%5B%22%E5%90%8E%E8%AF%BE%3A%20%E9%A1%B5%E4%B8%8E%E6%A7%BD%22%5D%0A%20%20MV%20--%3E%20PAGE%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[t("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"优化器可以把视图当改写的匹配对象：若物化结果能覆盖当前查询，就改成扫描该副本（视图匹配）。这与索引的角色相近，但是「预计算的查询」而不是「预计算的查找结构」。虚视图则把逻辑树变大，下推仍然适用。",-1)),a[5]||(a[5]=E("p",null,"更新异常在视图上更尖：一张视图行可能对应多张基表上的组合，插入无法唯一分解。因此主干把视图首先当读接口；可更新子集是工程特例。",-1)),a[6]||(a[6]=E("h2",{id:"边界",tabindex:"-1"},[t("边界 "),E("a",{class:"header-anchor",href:"#边界","aria-label":'Permalink to "边界"'},"​")],-1)),a[7]||(a[7]=E("p",null,"本课不讲流式物化、列存 Cube 的全部 OLAP 栈。也不把缓存失效协议写细。物理上物化结果仍是后课的页与堆文件；本课只决定「有没有这一份关系副本」。",-1)),a[8]||(a[8]=E("p",null,"临时表与 CTE 不是物化视图：它们的寿命是查询或会话，不进入模式的持久外模式。后课默认：用户可以面对视图；存储引擎看到的是基表（及可选的物化副本）上的页。",-1)),(l(),i(n,null,{default:e(()=>[s(r,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20DML%5B%22%E5%9F%BA%E8%A1%A8%E6%8F%92%E5%85%A5%2F%E6%9B%B4%E6%96%B0%22%5D%20--%3E%20DELTA%5B%22%E5%86%99%E5%87%BA%20delta%22%5D%0A%20%20DELTA%20--%3E%20MODE%7B%22%E7%BB%B4%E6%8A%A4%E7%AD%96%E7%95%A5%3F%22%7D%0A%20%20MODE%20--%20%22%E7%AB%8B%E5%8D%B3%22%20--%3E%20INC%5B%22%E5%A2%9E%E9%87%8F%E8%A7%84%E5%88%99%E6%8E%A8%E8%A7%86%E5%9B%BE%20delta%22%5D%0A%20%20INC%20--%3E%20MV%5B%22%E7%89%A9%E5%8C%96%E8%A1%A8%E4%B8%8E%E5%9F%BA%E8%A1%A8%E4%BF%9D%E6%8C%81%E4%B8%80%E8%87%B4%22%5D%0A%20%20MODE%20--%20%22%E5%BB%B6%E8%BF%9F%22%20--%3E%20STALE%5B%22%E6%A0%87%E8%AE%B0%E8%BF%87%E6%9C%9F%2C%20%E8%AF%BB%E5%88%B0%E6%97%A7%E5%BF%AB%E7%85%A7%22%5D%0A%20%20STALE%20--%3E%20REFRESH%5B%22%E5%88%B7%E6%96%B0%E7%AA%97%E5%8F%A3%E5%85%A8%E9%87%8F%E6%88%96%E5%A2%9E%E9%87%8F%E9%87%8D%E7%AE%97%22%5D%0A%20%20REFRESH%20--%3E%20MV%0A%20%20MV%20--%3E%20Q%5B%22%E6%9F%A5%E8%AF%A2%E6%89%AB%E5%89%AF%E6%9C%AC%2C%20%E5%85%8D%E8%BF%9E%E6%8E%A5%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[9]||(a[9]=A('<p><span class="marginnote">常见误区：初学者容易把物化视图当成「免费加速」，实际上它是一份会过期的副本——立即维护让每次写入变慢，延迟刷新让读者可能拿到旧数；选哪种取决于业务能容忍多陈旧，而不是哪个听起来更快。</span></p><p>外模式可以宽，内模式可以窄。用户看见的名字不必等于堆文件的名字，这是独立性在本课的落点。</p><p><span class="marginnote">数字实例：报表每天扫 1 亿次订单明细做三表连接、聚合出 5000 行日汇总。虚视图每次跑都付 1 亿行的连接；物化后每次查询只扫 5000 行，代价是把「每次 1 亿」换成「每笔写入多做一点增量维护」——查询越频繁、视图越小，这笔交换越划算。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>分解之后用视图恢复外模式；虚的展开，实的维护。</li><li>读匹配可以省连接；写视图一般没有唯一翻译。</li><li>元组落在哪一页、哪一个槽，是后课缺口。</li><li>出处：Date；Gupta and Mumick；Garcia-Molina, Ullman and Widom。</li></ul>',5))])}const c=o(p,[["render",m]]);export{C as __pageData,c as default};
